import React, { useState, useEffect } from 'react';
import {
    Calendar,
    MapPin,
    Clock,
    Heart,
    ChevronDown,
    Music,
    Music2,
    Upload,
    Phone,
    Home,
    MailOpen
} from 'lucide-react';

const App = () => {
    const [activeTab, setActiveTab] = useState('home');
    const [isPlaying, setIsPlaying] = useState(false);
    const [isVisible, setIsVisible] = useState(false);

    const [timeLeft, setTimeLeft] = useState({
        days: 0, hours: 0, minutes: 0, seconds: 0
    });

    const weddingDateLabel = "8th of September 2026";
    const weddingTime = "12:30:00 PM";
    const locationAddress = "178/03, Welipitiya Road, Koledanda, Weligama, 81700";
    const contactNumber = "+94 77 148 3381";
    const googleDriveLink = "https://drive.google.com/drive/folders/your-shared-folder-id";
    const mapEmbedUrl = "https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3968.17387396652!2d80.4183!3d5.9723!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x3ae140656a9e1875%3A0x6a0a09a547285514!2sWeligama!5e0!3m2!1sen!2slk!4v1700000000000!5m2!1sen!2slk";

    useEffect(() => {
        const targetDate = new Date("September 8, 2026 12:30:00").getTime();
        const interval = setInterval(() => {
            const now = new Date().getTime();
            const distance = targetDate - now;
            if (distance < 0) {
                clearInterval(interval);
                return;
            }
            setTimeLeft({
                days: Math.floor(distance / (1000 * 60 * 60 * 24)),
                hours: Math.floor((distance % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60)),
                minutes: Math.floor((distance % (1000 * 60 * 60)) / (1000 * 60)),
                seconds: Math.floor((distance % (1000 * 60)) / 1000)
            });
        }, 1000);
        return () => clearInterval(interval);
    }, []);

    useEffect(() => {
        setIsVisible(true);
    }, [activeTab]);

    const TabButton = ({ id, label, icon: Icon }) => (
        <button
            onClick={() => {
                setIsVisible(false);
                setTimeout(() => {
                    setActiveTab(id);
                    window.scrollTo({ top: 0, behavior: 'smooth' });
                }, 300);
            }}
            className={`flex items-center space-x-2 px-5 py-2.5 rounded-full transition-all duration-500 ${
                activeTab === id
                    ? 'bg-[#D4AF37] text-white shadow-xl scale-105'
                    : 'text-[#4A4238] hover:bg-[#D4AF37]/10'
            }`}
        >
            <Icon size={16} />
            <span className="font-sans text-[10px] font-bold uppercase tracking-widest">{label}</span>
        </button>
    );

    return (
        <div className="min-h-screen bg-[#FFFBF5] text-[#4A4238] font-serif overflow-x-hidden">
            <div className="fixed inset-0 z-0 pointer-events-none overflow-hidden">
                <div className="absolute top-0 left-0 w-full h-full bg-[url('https://www.transparenttextures.com/patterns/silk.png')] opacity-10"></div>
                <div className="absolute top-[-20%] left-[-10%] w-[60%] h-[60%] bg-[#D4AF37]/10 blur-[150px] rounded-full animate-pulse"></div>
                <div className="absolute bottom-[-10%] right-[-10%] w-[50%] h-[50%] bg-[#E8DCC4]/30 blur-[150px] rounded-full animate-pulse" style={{ animationDelay: '3s' }}></div>
            </div>

            <nav className="fixed top-0 left-0 w-full z-50 bg-white/70 backdrop-blur-lg border-b border-[#D4AF37]/10 px-6 py-4">
                <div className="max-w-6xl mx-auto flex justify-between items-center">
                    <h2 className="text-xl md:text-2xl italic tracking-tighter font-light">
                        Shazeen <span className="text-[#D4AF37]">&</span> Shimra
                    </h2>
                    <div className="hidden md:flex items-center space-x-2">
                        <TabButton id="home" label="Home" icon={Home} />
                        <TabButton id="invitation" label="Invitation" icon={MailOpen} />
                        <TabButton id="location" label="Location" icon={MapPin} />
                    </div>
                    <div className="md:hidden flex space-x-6">
                        <button onClick={() => setActiveTab('home')} className={activeTab === 'home' ? 'text-[#D4AF37]' : 'opacity-40'}><Home size={22}/></button>
                        <button onClick={() => setActiveTab('invitation')} className={activeTab === 'invitation' ? 'text-[#D4AF37]' : 'opacity-40'}><MailOpen size={22}/></button>
                        <button onClick={() => setActiveTab('location')} className={activeTab === 'location' ? 'text-[#D4AF37]' : 'opacity-40'}><MapPin size={22}/></button>
                    </div>
                </div>
            </nav>

            <main className={`relative z-10 pt-28 pb-20 px-6 transition-all duration-700 transform ${isVisible ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-10'}`}>

                {activeTab === 'home' && (
                    <section className="min-h-[80vh] flex flex-col items-center justify-center text-center">
                        <div className="animate-fade-in-up space-y-4">
              <span className="inline-block px-4 py-1 border-y border-[#D4AF37] text-[#D4AF37] font-sans text-[10px] uppercase tracking-[0.5em] mb-4">
                In the name of Allah
              </span>

                            <h1 className="text-4xl text-[#D4AF37] sm:text-5xl md:text-6xl lg:text-8xl font-light italic leading-tight">
                                Shazeen <span className="text-shining-ampersand mx-2 md:mx-4">&</span> Shimra
                            </h1>

                            <p className="text-lg md:text-2xl opacity-60 italic max-w-lg mx-auto leading-relaxed mt-4">
                                Together with their families, cordially invite you to celebrate their Fathiha Ceremony.
                            </p>

                            <div className="pt-8 pb-4">
                                <div className="text-2xl md:text-4xl font-light tracking-[0.1em] text-[#4A4238] italic">
                                    {weddingDateLabel}
                                </div>
                            </div>

                            <div className="py-8 grid grid-cols-2 md:grid-cols-4 gap-4 md:gap-6 max-w-2xl mx-auto w-full">
                                {[
                                    { label: 'Days', val: timeLeft.days },
                                    { label: 'Hours', val: timeLeft.hours },
                                    { label: 'Minutes', val: timeLeft.minutes },
                                    { label: 'Seconds', val: timeLeft.seconds }
                                ].map((unit, i) => (
                                    <div key={i} className="relative group scale-90 md:scale-100">
                                        <div className="bg-white/40 backdrop-blur-md border border-white/60 p-4 rounded-2xl shadow-xl shadow-[#D4AF37]/5 transform transition-transform group-hover:-translate-y-1 duration-500">
                                            <div className="text-3xl md:text-4xl font-light text-[#D4AF37] tabular-nums mb-1">
                                                {String(unit.val).padStart(2, '0')}
                                            </div>
                                            <div className="text-[8px] font-sans font-bold uppercase tracking-[0.2em] opacity-40">
                                                {unit.label}
                                            </div>
                                        </div>
                                    </div>
                                ))}
                            </div>

                            <div className="pt-6">
                                <button
                                    onClick={() => setActiveTab('invitation')}
                                    className="group flex flex-col items-center mx-auto space-y-3 text-[#D4AF37] hover:opacity-80 transition-opacity"
                                >
                                    <span className="font-sans text-[10px] uppercase tracking-[0.4em] font-bold">Discover Details</span>
                                    <ChevronDown className="animate-bounce" size={24} />
                                </button>
                            </div>
                        </div>
                    </section>
                )}

                {activeTab === 'invitation' && (
                    <section className="max-w-4xl mx-auto py-12">
                        <div className="bg-white/50 backdrop-blur-xl border border-white/80 rounded-[3.5rem] p-10 md:p-20 shadow-2xl shadow-[#D4AF37]/5 relative overflow-hidden text-center space-y-12">
                            <div className="absolute -top-10 -right-10 w-40 h-40 bg-[#D4AF37]/5 rounded-full blur-3xl"></div>
                            <Heart className="mx-auto text-[#D4AF37] opacity-30 animate-pulse" size={48} />
                            <h2 className="text-4xl md:text-6xl font-light italic">The Invitation</h2>
                            <p className="text-lg md:text-2xl leading-relaxed opacity-70 max-w-2xl mx-auto font-light">
                                Welcome to our Fathiha Ceremony! We are thrilled to share our journey with you.
                                Join us as we embark on this beautiful adventure together.
                            </p>
                            <div className="grid md:grid-cols-3 gap-10 py-12 border-y border-[#D4AF37]/10">
                                <div className="space-y-3">
                                    <MapPin className="mx-auto text-[#D4AF37]" size={24} />
                                    <p className="font-sans text-[10px] uppercase font-bold tracking-widest opacity-40">Where</p>
                                    <p className="text-xl">At Our Residence</p>
                                </div>
                                <div className="space-y-3">
                                    <Calendar className="mx-auto text-[#D4AF37]" size={24} />
                                    <p className="font-sans text-[10px] uppercase font-bold tracking-widest opacity-40">When</p>
                                    <p className="text-xl">{weddingDateLabel}</p>
                                </div>
                                <div className="space-y-3">
                                    <Clock className="mx-auto text-[#D4AF37]" size={24} />
                                    <p className="font-sans text-[10px] uppercase font-bold tracking-widest opacity-40">Time</p>
                                    <p className="text-xl">{weddingTime}</p>
                                </div>
                            </div>
                            <div className="pt-8 space-y-6">
                                <a
                                    href={googleDriveLink}
                                    target="_blank"
                                    rel="noreferrer"
                                    className="inline-flex items-center space-x-4 px-10 py-5 bg-[#D4AF37] text-white rounded-full font-sans text-xs font-bold uppercase tracking-[0.2em] hover:scale-105 transition-all shadow-xl shadow-[#D4AF37]/30"
                                >
                                    <Upload size={18} />
                                    <span>Share Your Captures</span>
                                </a>
                            </div>
                        </div>
                    </section>
                )}

                {activeTab === 'location' && (
                    <section className="max-w-5xl mx-auto py-12 space-y-12">
                        <div className="text-center space-y-4">
                            <h2 className="text-4xl md:text-5xl font-light italic">Location</h2>
                            <div className="w-12 h-[1px] bg-[#D4AF37] mx-auto opacity-40"></div>
                        </div>
                        <div className="grid lg:grid-cols-5 gap-10 items-stretch">
                            <div className="lg:col-span-2 flex flex-col justify-between bg-white/50 p-10 rounded-[2.5rem] border border-white/80 shadow-lg">
                                <div className="space-y-10">
                                    <div className="space-y-4">
                                        <div className="flex items-center space-x-3 text-[#D4AF37]">
                                            <Home size={22} />
                                            <h3 className="font-sans text-[10px] font-bold uppercase tracking-[0.2em]">Residence Address</h3>
                                        </div>
                                        <p className="text-2xl leading-relaxed font-light">{locationAddress}</p>
                                    </div>
                                    <div className="space-y-4">
                                        <div className="flex items-center space-x-3 text-[#D4AF37]">
                                            <Phone size={22} />
                                            <h3 className="font-sans text-[10px] font-bold uppercase tracking-[0.2em]">R.S.V.P & Contact</h3>
                                        </div>
                                        <a href={`tel:${contactNumber}`} className="text-2xl block hover:text-[#D4AF37] transition-colors font-light">
                                            {contactNumber}
                                        </a>
                                    </div>
                                </div>
                                <a
                                    href="https://www.google.com/maps/dir/?api=1&destination=Weligama"
                                    target="_blank"
                                    rel="noreferrer"
                                    className="mt-12 block text-center py-5 bg-white border border-[#D4AF37]/20 text-[#D4AF37] rounded-2xl font-sans text-[10px] font-bold uppercase tracking-[0.3em] hover:bg-[#D4AF37] hover:text-white transition-all"
                                >
                                    Get Directions
                                </a>
                            </div>
                            <div className="lg:col-span-3 rounded-[3rem] overflow-hidden shadow-2xl border-[12px] border-white h-[500px] relative">
                                <iframe
                                    src={mapEmbedUrl}
                                    className="w-full h-full grayscale-[0.2]"
                                    style={{ border: 0 }}
                                    allowFullScreen=""
                                    loading="lazy"
                                    referrerPolicy="no-referrer-when-downgrade"
                                    title="Venue Map"
                                ></iframe>
                            </div>
                        </div>
                    </section>
                )}
            </main>

            <button
                onClick={() => setIsPlaying(!isPlaying)}
                className="fixed bottom-8 right-8 w-14 h-14 bg-white/90 backdrop-blur-md rounded-full shadow-2xl flex items-center justify-center text-[#D4AF37] hover:scale-110 transition-transform z-50 border border-[#D4AF37]/20"
            >
                {isPlaying ? <Music2 className="animate-pulse" /> : <Music />}
            </button>

            <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,400;0,700;1,400&family=Montserrat:wght@300;400;700&display=swap');
        
        body { font-family: 'Playfair Display', serif; -webkit-font-smoothing: antialiased; }
        .font-sans { font-family: 'Montserrat', sans-serif; }

        @keyframes fade-in-up {
          from { opacity: 0; transform: translateY(30px); }
          to { opacity: 1; transform: translateY(0); }
        }

        .animate-fade-in-up {
          animation: fade-in-up 1.5s cubic-bezier(0.16, 1, 0.3, 1) forwards;
        }

        /* Shining Ampersand Animation */
        .text-shining-ampersand {
          background: linear-gradient(
            to right, 
            #a6a6a6 20%, 
            #ffffff 40%, 
            #ffffff 60%, 
            #a6a6a6 80%
          );
          background-size: 200% auto;
          color: transparent;
          -webkit-background-clip: text;
          background-clip: text;
          display: inline-block;
          animation: shine 3s linear infinite;
          text-shadow: 0 0 15px rgba(255, 255, 255, 0.1);
          font-style: normal;
        }

        @keyframes shine {
          to {
            background-position: 200% center;
          }
        }

        @media (max-width: 640px) {
          h1 { font-size: 2.8rem !important; }
        }
      `}</style>
        </div>
    );
};

export default App;
